import requests
from bs4 import BeautifulSoup
import pandas as pd
from io import StringIO

def task_func(url, table_id):
    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.exceptions.HTTPError:
        raise
    except requests.exceptions.RequestException as exc:
        raise requests.exceptions.HTTPError(str(exc)) from exc

    soup = BeautifulSoup(response.text, "html.parser")
    table = soup.find("table", id=table_id)

    if table is None:
        raise ValueError("Table with the specified ID not found.")

    rows = table.find_all("tr")
    if not rows:
        return pd.DataFrame()

    headers = None
    data = []

    for row in rows:
        cells = row.find_all(["th", "td"])
        if not cells:
            continue

        values = [cell.get_text(strip=True) for cell in cells]

        if headers is None and all(cell.name == "th" for cell in cells):
            headers = values
            continue

        data.append(values)

    if headers is not None:
        width = len(headers)
        normalized = [
            values[:width] + [None] * max(0, width - len(values))
            for values in data
        ]
        return pd.DataFrame(normalized, columns=headers)

    return pd.DataFrame(data)
